body{font-family:Arial,sans-serif;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{height:64px;background:#1A1108;color:#C9A84C;display:flex;align-items:center;justify-content:space-between;padding:0 40px}.logo{font:28px Georgia,serif}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.header{background:#fff;padding:30px 40px;border-bottom:1px solid #E8E0D0}.title{font:34px Georgia,serif}.main{max-width:900px;margin:auto;padding:30px 40px}.card{background:#fff;margin-bottom:20px;box-shadow:0 2px 12px #0000000f}.head,.foot{padding:14px 20px;border-bottom:1px solid #E8E0D0;display:flex;justify-content:space-between}.body{padding:20px;display:flex;gap:16px}.img{width:80px;height:80px;background:#E8E0D0;display:flex;align-items:center;justify-content:center;font-size:28px}.img img{width:80px;height:80px;object-fit:cover}.name{font:20px Georgia,serif}.store{color:#C9A84C;font-size:12px;margin:5px 0 10px}.meta{color:#666;font-size:13px;display:flex;gap:18px;flex-wrap:wrap}.foot{border-top:1px solid #E8E0D0;border-bottom:0;background:#FDFAF5}.status{padding:5px 10px;border-radius:20px;font-size:12px}.empty{text-align:center;padding:70px;color:#888}.empty a{display:inline-block;margin-top:15px;padding:12px 24px;background:#1A1108;color:#C9A84C;text-decoration:none}@media(max-width:650px){.main{padding:20px}.nav,.header{padding-left:20px;padding-right:20px}}</style></head><body>
